#include "vrm-rest-consumer-fixtures.hpp"
#include "dome/creation.hpp"
int main(int argc,char**argv)try{if(argc!=2)return 2;std::filesystem::create_directories(argv[1]);for(bool metric:{false,true}){Scene scene;auto group=append_humanoid(scene,{},"Native CC0",{},64);if(metric)scene.group(group).affine_edit=std::make_shared<const NativeAffineEdit>(AffineTransform(std::array<double,16>{-1.1,0,0,0,.2,.9,0,0,.1,.05,1.2,0,.3,-.1,.2,1}));auto surfaces=scene.surfaces();const auto &a=*surfaces[0].appearance;auto inverse=a.source_basis_quaternion->inverse();auto path=std::filesystem::path(argv[1])/(metric?"metric.vrm":"identity.vrm");export_vrm(surfaces,path);cgltf_options cg{};cgltf_data*raw=nullptr;if(cgltf_parse_file(&cg,path.c_str(),&raw)!=cgltf_result_success)throw std::runtime_error("Parse failed");std::unique_ptr<cgltf_data,decltype(&cgltf_free)>owner(raw,cgltf_free);if(cgltf_load_buffers(&cg,raw,path.c_str())!=cgltf_result_success)throw std::runtime_error("Buffers failed");double max=0;size_t corners=0;for(size_t n=0;n<raw->nodes_count;++n){auto&node=raw->nodes[n];if(!node.mesh)continue;auto part=size_t(node.mesh-raw->meshes);const auto&s=surfaces.at(part);auto mesh=s.preview_mesh();auto world=s.world_matrix();auto&primitive=node.mesh->primitives[0];for(size_t c=0;c<mesh.indices.size();++c){auto p=mesh.positions[mesh.indices[c]];auto w=world.point({p.x,p.y,p.z});auto expected=inverse.rotate({float(w[0]),float(w[1]),float(w[2])});auto actual=consume(node,cgltf_accessor_read_index(primitive.indices,c));max=std::max(max,double(length(actual-expected)));++corners;}}std::cout<<"metric="<<metric<<" corners="<<corners<<" max="<<max<<std::endl;if(max>2e-5)throw std::runtime_error("Creator native-affine basis mismatch");check(true,"All actual CC0 source-space skin corners follow full native affine conjugation");}return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
